const {Promise} = require('bluebird');
const {request} = require('request');
const {fs} = require('fs');

const commentBot = {
   comment: (url, comment) => {
       return new Promise((resolve, reject) => {
           request({
               url: url,
               method: 'POST',
               body: comment,
               headers: {
                   'Content-Type': 'application/json',
                   'Content-Length': Buffer.byteLength(comment)}
           }).then(response => {return response.status === 200;}).then(response => {fs.writeFile('./comments.txt', response.body, (err) => {
                   if (err) {
                       reject(err);}
                   resolve();
               });
           }).catch(err => {reject(err);});
       });
   }
};

module.exports = commentBot;

